import{_ as t,o as a,c as i,a2 as n}from"./chunks/framework.CFuv5BrO.js";const u=JSON.parse(`{"title":"Frontend and Mobile Experience","description":"Hearth's frontend design principles, information architecture, Task cards, approvals, Artifact Center, mobile, accessibility, and experience metrics.","frontmatter":{"title":"Frontend and Mobile Experience","description":"Hearth's frontend design principles, information architecture, Task cards, approvals, Artifact Center, mobile, accessibility, and experience metrics.","outline":[2,3]},"headers":[],"relativePath":"en/architecture/frontend-experience.md","filePath":"en/architecture/frontend-experience.md","lastUpdated":null}`),r={name:"en/architecture/frontend-experience.md"};function o(s,e,l,d,c,h){return a(),i("div",null,[...e[0]||(e[0]=[n('<p class="eyebrow">FRONTEND &amp; MOBILE</p><h1 id="frontend-and-mobile-experience" tabindex="-1">Frontend and Mobile Experience <a class="header-anchor" href="#frontend-and-mobile-experience" aria-label="Permalink to &quot;Frontend and Mobile Experience&quot;">​</a></h1><p class="lead">Users only need to know three things: what the Agent is doing, whether they are needed, and where to click next. The frontend is not an after-the-fact wrapper layer.</p><h2 id="frontend-and-mobile-experience-1" tabindex="-1">Frontend and Mobile Experience <a class="header-anchor" href="#frontend-and-mobile-experience-1" aria-label="Permalink to &quot;Frontend and Mobile Experience&quot;">​</a></h2><p>Hearth&#39;s frontend is not a console that displays the Agent&#39;s internal architecture; it is a quiet attention interface.</p><h3 id="design-principles" tabindex="-1">Design Principles <a class="header-anchor" href="#design-principles" aria-label="Permalink to &quot;Design Principles&quot;">​</a></h3><ol><li><strong>Task-first</strong>: Users see the work to be completed, not models, tools, or threads;</li><li><strong>One state, one primary action</strong>: At any moment, a Task card has only one action most worth clicking;</li><li><strong>Progressive disclosure</strong>: By default, show only the goal, status, evidence, and next step;</li><li><strong>Quiet by default</strong>: Do not interrupt when nothing requires a person;</li><li><strong>Honest status</strong>: Do not disguise running as almost complete, and do not display a model&#39;s claim of completion as actually completed;</li><li><strong>Mobile parity</strong>: Mobile devices can handle viewing, approval, takeover, initiation, and notifications;</li><li><strong>No internal jargon</strong>: Worker, Harness, Token, and Mandate do not appear in the main interface;</li><li><strong>Interface first</strong>: For each increment, first clarify what users see, what they can click, and how to recover after failure, then connect the backend implementation.</li></ol><p>The frontend is not a presentation layer added after the backend is complete, but part of the product&#39;s vertical slice. Stage 0 validates the information architecture with prototypes; Stage 1 connects real pages to real states; after that, every stage projects newly added capabilities into an actionable interface. A feature is considered ready for stage acceptance only when it has a complete user path, evidence, and recovery entry points in the browser.</p><h3 id="information-architecture" tabindex="-1">Information Architecture <a class="header-anchor" href="#information-architecture" aria-label="Permalink to &quot;Information Architecture&quot;">​</a></h3><p>The main navigation keeps four items:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Today  |  Needs You  |  Artifacts  |  Settings</span></span></code></pre></div><ul><li><strong>Today</strong>: what is in progress, just completed, and what comes next;</li><li><strong>Needs You</strong>: approvals, missing information, failure takeover, and exceptions;</li><li><strong>Artifacts</strong>: reports, documents, code, spreadsheets, screenshots, receipts;</li><li><strong>Settings</strong>: connections, memory, permissions, devices, notifications, and budgets.</li></ul><p>&quot;New Task&quot; is a global action and does not occupy a navigation item. Use <code>⌘K</code> / <code>Ctrl+K</code> on desktop and a clearly visible floating button on mobile.</p><h3 id="home" tabindex="-1">Home <a class="header-anchor" href="#home" aria-label="Permalink to &quot;Home&quot;">​</a></h3><p>The first screen answers: what is happening today, what needs me, what is in progress, and what was recently completed. By default, do not show tokens, model names, executor names, internal steps, or debug logs; view them in the details when needed.</p><h3 id="task-card" tabindex="-1">Task Card <a class="header-anchor" href="#task-card" aria-label="Permalink to &quot;Task Card&quot;">​</a></h3><p>A task card should answer:</p><ul><li>What is this task?</li><li>What step is it at now?</li><li>Is there an artifact or verification evidence?</li><li>Does it need me?</li><li>What can I do next?</li></ul><p>Fields include title, status, key stage progress, artifacts, verification, risks, primary action, and time. Each status has only one primary action.</p><h3 id="status-and-primary-action" tabindex="-1">Status and Primary Action <a class="header-anchor" href="#status-and-primary-action" aria-label="Permalink to &quot;Status and Primary Action&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Status</th><th>What the user sees</th><th>Primary action</th></tr></thead><tbody><tr><td>Queued</td><td>Waiting for a device or time</td><td>Adjust priority</td></tr><tr><td>Running</td><td>Current stage</td><td>View progress</td></tr><tr><td>Waiting for approval</td><td>What is about to happen</td><td>Approve</td></tr><tr><td>Waiting for information</td><td>What is missing</td><td>Provide information</td></tr><tr><td>Failed</td><td>Cause and remediation</td><td>Recover/retry/hand off to a human</td></tr><tr><td>Completed</td><td>Artifacts and verification</td><td>View artifacts</td></tr></tbody></table><h3 id="needs-you" tabindex="-1">Needs You <a class="header-anchor" href="#needs-you" aria-label="Permalink to &quot;Needs You&quot;">​</a></h3><p>&quot;Needs You&quot; collects only items that genuinely block a person: approvals, missing information, failure takeover, and high-risk confirmation. Pure status changes and failures that can be retried automatically do not enter.</p><h3 id="approval-interface" tabindex="-1">Approval Interface <a class="header-anchor" href="#approval-interface" aria-label="Permalink to &quot;Approval Interface&quot;">​</a></h3><p>An approval card must let the user decide within ten seconds: action, account, recipient/resource, attachments and content, reversibility, validity period, and failure compensation. High-risk actions show the real scope, diff, secondary confirmation, and how to undo.</p><h3 id="artifact-center" tabindex="-1">Artifact Center <a class="header-anchor" href="#artifact-center" aria-label="Permalink to &quot;Artifact Center&quot;">​</a></h3><p>Artifacts are inspectable deliverables, not an attachment list:</p><ul><li>Version, source task, and executor;</li><li>Generation time, hash, and size;</li><li>Verification results and evidence;</li><li>Preview, download, copy link;</li><li>Diff against the previous version;</li><li>Related approvals and receipts;</li><li>Delete, archive, and export.</li></ul><h3 id="details-and-timeline" tabindex="-1">Details and Timeline <a class="header-anchor" href="#details-and-timeline" aria-label="Permalink to &quot;Details and Timeline&quot;">​</a></h3><p>The details page shows goals, constraints, plan, key tool calls, artifacts and verification, approvals and receipts, errors/retries/rerouting, budget and cost, related memory, and skills. By default, do not show the model&#39;s internal thought process; show auditable events, evidence, and decision reasons.</p><h3 id="new-task" tabindex="-1">New Task <a class="header-anchor" href="#new-task" aria-label="Permalink to &quot;New Task&quot;">​</a></h3><p>Supports natural language, files and images, project/contact/deadline, autonomy level, and acceptance criteria preview. When the user only writes &quot;help me organize this,&quot; the system should generate an editable task card rather than immediately executing without boundaries.</p><h3 id="takeover-interface" tabindex="-1">Takeover Interface <a class="header-anchor" href="#takeover-interface" aria-label="Permalink to &quot;Takeover Interface&quot;">​</a></h3><p>Show the current browser/desktop and clearly state what the user needs to do; pause automatic input; allow operations, annotations, and additional information; record the state before and after takeover; support handing back, narrowing scope, and termination.</p><h3 id="notifications" tabindex="-1">Notifications <a class="header-anchor" href="#notifications" aria-label="Permalink to &quot;Notifications&quot;">​</a></h3><p>Use only for high-signal events: approval needed, additional information needed, unrecoverable failure, completion the user explicitly cares about, device offline blocking, and security anomalies.</p><p>Rules: aggregate by task, quiet hours, summary before details, redact push content, tap to go directly to the action, do not bypass after a channel is disabled, and evaluate notification frequency together with task value.</p><h3 id="mobile" tabindex="-1">Mobile <a class="header-anchor" href="#mobile" aria-label="Permalink to &quot;Mobile&quot;">​</a></h3><p>Mobile prioritizes PWA; Stage 4 handles only five things:</p><ol><li>View tasks and artifacts;</li><li>Approve high-risk actions;</li><li>Take over abnormal tasks;</li><li>Start new tasks;</li><li>Receive high-signal notifications.</li></ol><p>Mobile should not: run a full Agent by default, hold long-term primary credentials, directly expose local ports, execute high-risk tasks unbounded in the background, or leak sensitive information in push body text.</p><p>Security design: secure tunnel or push relay, short-lived codes and public-key pairing, session expiration and biometrics, approvals bound to nonce/parameters/expiration time, revocable on device loss, and offline read-only cache with no side effects.</p><h3 id="accessibility-and-performance" tabindex="-1">Accessibility and Performance <a class="header-anchor" href="#accessibility-and-performance" aria-label="Permalink to &quot;Accessibility and Performance&quot;">​</a></h3><p>Complete main flows with a keyboard; do not rely on color alone; screen readers and accessibility labels; reduced motion and dark mode; fast first-screen loading and long-list virtualization; show cache and clear status on weak networks; do not truncate key actions in Chinese or English; keep the primary action within reach for one-handed use.</p><h3 id="experience-metrics" tabindex="-1">Experience Metrics <a class="header-anchor" href="#experience-metrics" aria-label="Permalink to &quot;Experience Metrics&quot;">​</a></h3><ul><li>Time for the user to understand the current status;</li><li>Time from &quot;Needs You&quot; to completing an approval;</li><li>Approval misclick rate and undo rate;</li><li>Number of interruptions per task;</li><li>Success rate of completing key actions on mobile;</li><li>Processing rate after a notification is opened;</li><li>Number of times artifacts or recovery entry points cannot be found.</li></ul><h2 id="relationship-to-mvp" tabindex="-1">Relationship to MVP <a class="header-anchor" href="#relationship-to-mvp" aria-label="Permalink to &quot;Relationship to MVP&quot;">​</a></h2><p>The MVP must let users complete creation, viewing, approval drills, cancellation, retry, recovery, and artifact retrieval through the browser. Stage 0 starts with a clickable prototype, Stage 1 D1.1 connects real task status, and D1.3 reaches the full MVP.</p><p>An &quot;MVP&quot; without a real Web path does not hold; an interface without failure states and recovery entry points is not complete either.</p>',49)])])}const m=t(r,[["render",o]]);export{u as __pageData,m as default};
